catalogs.query:
begin transaction read only;
select jsonb_build_object(
'cronJobs',(select jsonb_agg(jsonb_build_object('id',jobid,'name',jobname,'active',active,'schedule',schedule,'expectedCommand',command='select wordpairs_hosting.tick();')) from cron.job where jobname='wordpairs-hosted-tick'),
'schedulerControls',(select jsonb_agg(jsonb_build_object('singleton',singleton,'enabled',enabled,'endpointRecognized',endpoint in('https://wordpairs.vercel.app/api/internal/deadlines','https://wordpairs-j9jf.vercel.app/api/internal/deadlines'),'endpointMatchesEnvironment',endpoint='https://wordpairs.vercel.app/api/internal/deadlines','lastStatus',last_status,'failures',failures)) from wordpairs_hosting.scheduler),
'schedulerSecretPresent',exists(select 1 from vault.secrets where name='wordpairs_scheduler_secret')
) as safe_worker_metadata;
commit;

begin transaction read only;
