securityMetadataQuery:
begin transaction read only;
select jsonb_build_object(
 'relations',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'rlsEnabled',c.relrowsecurity,'rlsForced',c.relforcerowsecurity) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind in('r','p') and (n.nspname in('wordpairs','wordpairs_hosting') or (n.nspname='realtime' and c.relname='messages'))),
 'policies',(select jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',policyname,'command',cmd,'roles',roles,'qualMd5',md5(coalesce(qual,'')),'checkMd5',md5(coalesce(with_check,'')),'mentionsOwnTopic',position('wordpairs-profile:' in coalesce(qual,''))>0,'mentionsSubject',position('request.jwt.claims' in coalesce(qual,''))>0 and position('sub' in coalesce(qual,''))>0,'mentionsBroadcast',position('broadcast' in coalesce(qual,''))>0) order by schemaname,tablename,policyname) from pg_policies where schemaname in('wordpairs','wordpairs_hosting') or(schemaname='realtime' and tablename='messages')),
 'schemaPrivileges',(select jsonb_agg(jsonb_build_object('role',r.rolname,'schema',n.nspname,'usage',has_schema_privilege(r.oid,n.oid,'USAGE'),'create',has_schema_privilege(r.oid,n.oid,'CREATE')) order by r.rolname,n.nspname) from pg_roles r cross join pg_namespace n where r.rolname in('anon','authenticated','service_role','wordpairs_app') and n.nspname in('wordpairs','wordpairs_hosting','realtime','vault','net')),
 'tablePrivileges',(select jsonb_agg(jsonb_build_object('role',r.rolname,'schema',n.nspname,'table',c.relname,'select',has_table_privilege(r.oid,c.oid,'SELECT'),'insert',has_table_privilege(r.oid,c.oid,'INSERT'),'update',has_table_privilege(r.oid,c.oid,'UPDATE'),'delete',has_table_privilege(r.oid,c.oid,'DELETE')) order by r.rolname,n.nspname,c.relname) from pg_roles r cross join pg_class c join pg_namespace n on n.oid=c.relnamespace where r.rolname in('anon','authenticated','service_role','wordpairs_app') and c.relkind in('r','p') and(n.nspname in('wordpairs','wordpairs_hosting') or(n.nspname='realtime' and c.relname='messages'))),
 'roles',(select jsonb_agg(jsonb_build_object('role',rolname,'superuser',rolsuper,'bypassRls',rolbypassrls,'canLogin',rolcanlogin) order by rolname) from pg_roles where rolname in('anon','authenticated','service_role','wordpairs_app')),
 'tickFunction',(select jsonb_build_object('exists',true,'securityDefiner',p.prosecdef,'definitionMd5',md5(pg_get_functiondef(p.oid)),'searchPathIsPgCatalog',p.proconfig @> array['search_path=pg_catalog']) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='wordpairs_hosting' and p.proname='tick' and p.pronargs=0),
 'tickExecutePrivileges',(select jsonb_agg(jsonb_build_object('role',r.rolname,'execute',has_function_privilege(r.oid,p.oid,'EXECUTE')) order by r.rolname) from pg_roles r cross join pg_proc p join pg_namespace n on n.oid=p.pronamespace where r.rolname in('anon','authenticated','service_role','wordpairs_app') and n.nspname='wordpairs_hosting' and p.proname='tick' and p.pronargs=0),
 'sqlSessionSchemaSettingPresent',current_setting('pgrst.db_schemas',true) is not null
) as safe_security_metadata;
commit;
